   Design tokens
   ============================================================ */
:root {
  --bg-base:      #0d0d0d;
  --bg-surface:   #161616;
  --bg-elevated:  #1e1e1e;
  --bg-overlay:   #252525;

  --text-primary:   #f0f0f0;
  --text-secondary: #a0a0a0;
  --text-muted:     #606060;

  --accent:        #e8c97e;
  --accent-hover:  #f5d98e;
  --accent-dim:    rgba(232, 201, 126, 0.15);

  --danger:  #e05c5c;
  --success: #5cbe8a;

  --border:       rgba(255, 255, 255, 0.08);
  --border-focus: rgba(232, 201, 126, 0.7);

  --radius-sm:  4px;
  --radius-md:  8px;
  --radius-lg:  16px;
  --radius-xl:  24px;

  --shadow-sm:  0 2px 8px rgba(0,0,0,.45);
  --shadow-md:  0 6px 24px rgba(0,0,0,.6);
  --shadow-lg:  0 16px 48px rgba(0,0,0,.75);

  --transition: 220ms cubic-bezier(.4,0,.2,1);

  --font-sans:  'Inter', system-ui, -apple-system, sans-serif;
  --font-serif: 'Playfair Display', Georgia, serif;
}

/* ============================================================
   Reset & base
   ============================================================ */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--bg-base);
  color: var(--text-primary);
  line-height: 1.6;
  overflow-x: hidden;
}

img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }

/* Focus visible */
:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 3px;
  border-radius: var(--radius-sm);
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: .5rem 1rem;
  background: var(--accent);
  color: #000;
  font-weight: 600;
  border-radius: var(--radius-sm);
  z-index: 9999;
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; }

/* ============================================================
   Typography helpers
   ============================================================ */
.serif { font-family: var(--font-serif); }

.section-label {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  font-size: .75rem;
  font-weight: 600;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--accent);
}
.section-label::before {
  content: '';
  display: block;
  width: 24px;
  height: 2px;
  background: var(--accent);
  border-radius: 2px;
  flex-shrink: 0;
}

/* ============================================================
   Layout helpers
   ============================================================ */
.container {
  width: min(1280px, 100% - 2rem);
  margin-inline: auto;
}

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
  margin-bottom: 2.5rem;
}

.section-title {
  font-family: var(--font-serif);
  font-size: clamp(1.6rem, 3vw, 2.2rem);
  font-weight: 700;
  line-height: 1.2;
  margin-top: .4rem;
}

.view-all {
  font-size: .85rem;
  font-weight: 600;
  letter-spacing: .05em;
  color: var(--accent);
  display: inline-flex;
  align-items: center;
  gap: .35rem;
  white-space: nowrap;
  transition: gap var(--transition);
}
.view-all:hover { gap: .6rem; }
.view-all svg { flex-shrink: 0; }

/* ============================================================
   Buttons
   ============================================================ */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .5rem;
  padding: .7rem 1.4rem;
  font-size: .9rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  transition: background var(--transition), color var(--transition), transform var(--transition), box-shadow var(--transition);
}
.btn:active { transform: scale(.97); }

.btn-primary {
  background: var(--accent);
  color: #000;
}
.btn-primary:hover {
  background: var(--accent-hover);
  box-shadow: 0 0 24px rgba(232,201,126,.35);
}

.btn-ghost {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid var(--border);
}
.btn-ghost:hover {
  background: var(--bg-elevated);
  border-color: rgba(255,255,255,.18);
}

.btn-icon {
  width: 40px;
  height: 40px;
  padding: 0;
  border-radius: 50%;
  background: var(--bg-elevated);
  color: var(--text-primary);
  border: 1px solid var(--border);
  transition: background var(--transition), border-color var(--transition);
}
.btn-icon:hover { background: var(--bg-overlay); border-color: rgba(255,255,255,.2); }
.btn-icon svg { pointer-events: none; }

/* ============================================================
   Badges
   ============================================================ */
.badge {
  display: inline-block;
  padding: .2rem .55rem;
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .05em;
  text-transform: uppercase;
  border-radius: var(--radius-sm);
}
.badge-sale   { background: var(--danger);  color: #fff; }
.badge-new    { background: var(--success); color: #000; }
.badge-hot    { background: var(--accent);  color: #000; }

/* ============================================================
   Header / Nav
   ============================================================ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13,13,13,.85);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border);
}

.header-inner {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  height: 64px;
  gap: 1rem;
