/* Logo */
.site-logo {
  font-family: var(--font-serif);
  font-size: 1.45rem;
  font-weight: 700;
  letter-spacing: .03em;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: .4rem;
}
.site-logo span { color: var(--accent); }

/* Primary nav */
.primary-nav { justify-self: center; }
.primary-nav ul { display: flex; gap: .25rem; }
.primary-nav a {
  padding: .45rem .8rem;
  font-size: .875rem;
