}
.primary-nav a:hover,
.primary-nav a[aria-current="page"] {
  color: var(--text-primary);
  background: var(--bg-elevated);
}

/* Header actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: .5rem;
  justify-self: end;
}

.cart-btn {
  position: relative;
}
.cart-count {
  position: absolute;
  top: -4px;
  right: -4px;
  width: 18px;
  height: 18px;
  background: var(--accent);
  color: #000;
  font-size: .65rem;
  font-weight: 700;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Mobile menu toggle */
.menu-toggle { display: none; }

/* ============================================================
   Mobile nav drawer
   ============================================================ */
.mobile-nav {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 200;
}
.mobile-nav.open { display: block; }

.mobile-nav-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(0,0,0,.7);
}

.mobile-nav-panel {
  position: absolute;
  top: 0;
  left: 0;
