  align-self: flex-end;
}

.mobile-nav-links { display: flex; flex-direction: column; gap: .25rem; }
.mobile-nav-links a {
  padding: .75rem 1rem;
  font-size: 1rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius-md);
  transition: color var(--transition), background var(--transition);
  display: block;
}
.mobile-nav-links a:hover { color: var(--text-primary); background: var(--bg-elevated); }

/* ============================================================
   Announcement bar
   ============================================================ */
.announcement-bar {
  background: var(--accent);
  color: #000;
  text-align: center;
  padding: .5rem 1rem;
  font-size: .8rem;
  font-weight: 600;
  letter-spacing: .04em;
}

/* ============================================================
   Hero
   ============================================================ */
.hero {
  position: relative;
  min-height: 88vh;
  display: flex;
  align-items: center;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 70% 70% at 70% 50%, rgba(232,201,126,.07) 0%, transparent 70%),
    radial-gradient(ellipse 50% 80% at 20% 80%, rgba(100,80,200,.08) 0%, transparent 60%),
    linear-gradient(160deg, #111 0%, #0a0a0a 100%);
}

/* Decorative grid lines */
.hero-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(255,255,255,.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,.03) 1px, transparent 1px);
  background-size: 60px 60px;
  mask-image: radial-gradient(ellipse 80% 80% at 50% 50%, black 30%, transparent 70%);
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 640px;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: .6rem;
  padding: .35rem .8rem;
  background: var(--accent-dim);
  border: 1px solid rgba(232,201,126,.25);
  border-radius: 100px;
  font-size: .75rem;
  font-weight: 600;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 1.5rem;
}
.hero-eyebrow-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent);
  animation: pulse 2s infinite;
}
@keyframes pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50%       { opacity: .5; transform: scale(.85); }
}

.hero-title {
  font-family: var(--font-serif);
  font-size: clamp(2.8rem, 7vw, 5rem);
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -.01em;
  margin-bottom: 1.25rem;
}
.hero-title em {
  font-style: normal;
  color: var(--accent);
}

.hero-subtitle {
  font-size: 1.1rem;
  color: var(--text-secondary);
  max-width: 480px;
  margin-bottom: 2.5rem;
  line-height: 1.7;
}

.hero-cta {
  display: flex;
  flex-wrap: wrap;
  gap: .75rem;
  align-items: center;
}

.hero-stats {
  display: flex;
  gap: 2.5rem;
  margin-top: 4rem;
  padding-top: 2rem;
  border-top: 1px solid var(--border);
  flex-wrap: wrap;
}
.hero-stat-value {
  font-family: var(--font-serif);
  font-size: 1.8rem;
  font-weight: 700;
  color: var(--accent);
}
.hero-stat-label {
  font-size: .8rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: .08em;
  margin-top: .1rem;
}

.hero-image-col {
  position: absolute;
  right: 0;
  top: 0;
  bottom: 0;
  width: 45%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero-image-frame {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
}

.hero-image-frame img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: .55;
  filter: saturate(.8);
}

.hero-image-frame::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, var(--bg-base) 0%, transparent 40%, transparent 70%, var(--bg-base) 100%);
  z-index: 1;
}
.hero-image-frame::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, var(--bg-base) 0%, transparent 20%, transparent 80%, var(--bg-base) 100%);
  z-index: 1;
}

/* ============================================================
   Category pills
   ============================================================ */
.categories-section {
  padding: 3rem 0;
  border-bottom: 1px solid var(--border);
}

.categories-list {
  display: flex;
  gap: .75rem;
  overflow-x: auto;
  scrollbar-width: none;
  padding-bottom: .5rem;
  -webkit-overflow-scrolling: touch;
}
.categories-list::-webkit-scrollbar { display: none; }

.category-pill {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  padding: .6rem 1.2rem;
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: 100px;
  font-size: .875rem;
  font-weight: 500;
  white-space: nowrap;
  color: var(--text-secondary);
  transition: all var(--transition);
  flex-shrink: 0;
}
.category-pill:hover,
.category-pill[aria-pressed="true"] {
  background: var(--accent-dim);
  border-color: rgba(232,201,126,.4);
  color: var(--accent);
}
.category-pill-icon { font-size: 1rem; }

/* ============================================================
   Product card
   ============================================================ */
.products-section { padding: 5rem 0; }

.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 1.5rem;
}

.product-card {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);
}
.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: rgba(255,255,255,.12);
}

.product-image-wrap {
  position: relative;
  aspect-ratio: 1 / 1;
  background: var(--bg-elevated);
  overflow: hidden;
}
.product-image-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 380ms ease;
}
.product-card:hover .product-image-wrap img { transform: scale(1.05); }

.product-badges {
  position: absolute;
  top: .75rem;
  left: .75rem;
  display: flex;
  flex-direction: column;
  gap: .35rem;
}

.product-actions-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 1rem;
  background: linear-gradient(transparent, rgba(0,0,0,.75));
  display: flex;
  gap: .5rem;
  transform: translateY(100%);
  transition: transform var(--transition);
}
.product-card:hover .product-actions-overlay,
.product-card:focus-within .product-actions-overlay {
  transform: translateY(0);
}
.product-actions-overlay .btn { flex: 1; font-size: .8rem; padding: .55rem .75rem; }

.product-wishlist {
  position: absolute;
  top: .75rem;
  right: .75rem;
}

.product-body {
  padding: 1.1rem;
  display: flex;
  flex-direction: column;
  gap: .4rem;
  flex: 1;
}

.product-brand {
  font-size: .75rem;
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--text-muted);
}

.product-name {
  font-size: .975rem;
  font-weight: 600;
  color: var(--text-primary);
  line-height: 1.35;
}

.product-rating {
  display: flex;
  align-items: center;
  gap: .4rem;
  font-size: .8rem;
  color: var(--text-secondary);
}
.stars { color: var(--accent); letter-spacing: .05em; font-size: .75rem; }

.product-price {
  display: flex;
  align-items: baseline;
  gap: .5rem;
  margin-top: .35rem;
}
.price-current {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text-primary);
}
.price-original {
  font-size: .875rem;
  color: var(--text-muted);
  text-decoration: line-through;
}
.price-savings {
  font-size: .75rem;
  font-weight: 600;
  color: var(--danger);
}

/* ============================================================
   Deals section
   ============================================================ */
.deals-section {
  padding: 5rem 0;
  background: var(--bg-surface);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.deals-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.5rem;
}

/* Featured deal — spans both rows on left */
.deal-card {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: box-shadow var(--transition), border-color var(--transition);
}
.deal-card:hover {
  box-shadow: var(--shadow-lg);
  border-color: rgba(255,255,255,.12);
}
.deal-card.deal-featured { grid-row: 1 / span 2; }

.deal-image-wrap {
  position: relative;
  aspect-ratio: 4 / 3;
  overflow: hidden;
  background: var(--bg-overlay);
}
.deal-card.deal-featured .deal-image-wrap { aspect-ratio: 3 / 4; flex: 1; }

.deal-image-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 380ms ease;
  filter: brightness(.85);
}
.deal-card:hover .deal-image-wrap img { transform: scale(1.04); }

.deal-image-wrap::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,.8) 0%, transparent 60%);
}

.deal-overlay-content {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 1.5rem;
  z-index: 1;
}
.deal-card.deal-featured .deal-overlay-content { padding: 2rem; }

.deal-tag {
  display: inline-block;
  padding: .25rem .65rem;
  background: var(--danger);
  color: #fff;
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  border-radius: var(--radius-sm);
  margin-bottom: .75rem;
}

.deal-title {
  font-family: var(--font-serif);
  font-size: 1.3rem;
  font-weight: 700;
  color: #fff;
  line-height: 1.2;
  margin-bottom: .5rem;
}
.deal-card.deal-featured .deal-title { font-size: 1.8rem; }

.deal-discount {
  font-size: .875rem;
  color: var(--accent);
  font-weight: 600;
  margin-bottom: 1rem;
}

/* Countdown */
.countdown {
  display: flex;
  gap: .5rem;
  margin-bottom: 1.25rem;
  flex-wrap: wrap;
}
.countdown-unit {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: rgba(0,0,0,.5);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: var(--radius-sm);
  padding: .4rem .65rem;
  min-width: 52px;
}
.countdown-value {
  font-size: 1.2rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  line-height: 1;
}
.countdown-label {
  font-size: .6rem;
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--text-muted);
  margin-top: .2rem;
}

/* Small deal card body */
.deal-body {
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: .4rem;
}
.deal-name { font-weight: 600; font-size: .95rem; }
.deal-price-row {
  display: flex;
  align-items: baseline;
  gap: .5rem;
}

/* ============================================================
   Editorial / lookbook section
   ============================================================ */
.editorial-section { padding: 5rem 0; }

.editorial-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 1.5rem;
}

.editorial-card {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform var(--transition), box-shadow var(--transition);
}
.editorial-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }
.editorial-card.editorial-featured { grid-column: 1 / span 2; }

.editorial-image-wrap {
  position: relative;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  background: var(--bg-elevated);
}
.editorial-card.editorial-featured .editorial-image-wrap { aspect-ratio: 16 / 8; }

.editorial-image-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 380ms ease;
  filter: brightness(.8) saturate(.9);
}
.editorial-card:hover .editorial-image-wrap img { transform: scale(1.04); }

.editorial-body {
  padding: 1.5rem;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: .5rem;
}

.editorial-category {
  font-size: .7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .1em;
  color: var(--accent);
}

.editorial-title {
  font-family: var(--font-serif);
  font-size: 1.15rem;
  font-weight: 700;
  line-height: 1.3;
  color: var(--text-primary);
}
.editorial-card.editorial-featured .editorial-title { font-size: 1.5rem; }

.editorial-excerpt {
  font-size: .875rem;
  color: var(--text-secondary);
  line-height: 1.65;
  flex: 1;
}

.editorial-meta {
  display: flex;
  align-items: center;
  gap: .75rem;
  font-size: .775rem;
  color: var(--text-muted);
  margin-top: .5rem;
}
.editorial-meta-sep { opacity: .4; }

/* ============================================================
   Newsletter section
   ============================================================ */
.newsletter-section {
  padding: 5rem 0;
  background: var(--bg-surface);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
}

.newsletter-headline {
  font-family: var(--font-serif);
  font-size: clamp(1.8rem, 3vw, 2.5rem);
  font-weight: 700;
  line-height: 1.15;
  margin-top: .5rem;
  margin-bottom: 1rem;
}

.newsletter-body {
  color: var(--text-secondary);
  font-size: .95rem;
  line-height: 1.7;
}

.newsletter-form { display: flex; flex-direction: column; gap: 1rem; }

.newsletter-field {
  display: flex;
  flex-direction: column;
  gap: .4rem;
}
.newsletter-field label {
  font-size: .8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: .07em;
  color: var(--text-secondary);
}
.newsletter-field input {
  padding: .8rem 1rem;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  color: var(--text-primary);
  font-family: inherit;
  font-size: .95rem;
  transition: border-color var(--transition);
  width: 100%;
}
.newsletter-field input:focus {
  outline: none;
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(232,201,126,.12);
}
.newsletter-field input::placeholder { color: var(--text-muted); }

.newsletter-submit { align-self: flex-start; }

.newsletter-disclaimer {
  font-size: .75rem;
  color: var(--text-muted);
  line-height: 1.5;
}

.form-success {
  display: none;
  padding: 1.25rem;
  background: rgba(92,190,138,.1);
  border: 1px solid rgba(92,190,138,.3);
  border-radius: var(--radius-md);
  color: var(--success);
  font-size: .9rem;
  font-weight: 500;
}

/* ============================================================
   Brands marquee
   ============================================================ */
.brands-section { padding: 3rem 0; }

.brands-track-wrap {
  overflow: hidden;
  -webkit-mask-image: linear-gradient(90deg, transparent, black 15%, black 85%, transparent);
  mask-image: linear-gradient(90deg, transparent, black 15%, black 85%, transparent);
}

.brands-track {
  display: flex;
  gap: 3rem;
  animation: marquee 28s linear infinite;
  width: max-content;
}
@media (prefers-reduced-motion: reduce) {
  .brands-track { animation: none; }
}

.brands-track:hover { animation-play-state: paused; }

@keyframes marquee {
  from { transform: translateX(0); }
  to   { transform: translateX(-50%); }
}

.brand-logo {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 40px;
  opacity: .35;
  transition: opacity var(--transition);
  font-family: var(--font-serif);
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: .05em;
  white-space: nowrap;
  color: var(--text-primary);
}
.brand-logo:hover { opacity: .7; }

/* ============================================================
   Footer
   ============================================================ */
.site-footer {
  background: var(--bg-surface);
  border-top: 1px solid var(--border);
  padding: 4rem 0 0;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 3rem;
  padding-bottom: 3rem;
  border-bottom: 1px solid var(--border);
}

.footer-brand p {
  font-size: .875rem;
  color: var(--text-secondary);
  line-height: 1.7;
  margin-top: .75rem;
  max-width: 280px;
}

.footer-social {
  display: flex;
  gap: .5rem;
  margin-top: 1.25rem;
}

.footer-col-title {
  font-size: .8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .1em;
  color: var(--text-primary);
  margin-bottom: 1.25rem;
}

.footer-links { display: flex; flex-direction: column; gap: .6rem; }
.footer-links a {
  font-size: .875rem;
  color: var(--text-secondary);
  transition: color var(--transition);
}
.footer-links a:hover { color: var(--text-primary); }

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
  padding: 1.5rem 0;
}

.footer-bottom p {
  font-size: .8rem;
  color: var(--text-muted);
}

.footer-legal {
  display: flex;
  gap: 1.25rem;
}
.footer-legal a {
  font-size: .8rem;
  color: var(--text-muted);
  transition: color var(--transition);
}
.footer-legal a:hover { color: var(--text-secondary); }

/* ============================================================
   Cart drawer
   ============================================================ */
.cart-drawer {
  position: fixed;
  inset: 0;
  z-index: 300;
  display: none;
}
.cart-drawer.open { display: block; }

.cart-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(0,0,0,.7);
}

.cart-panel {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  width: min(420px, 100vw);
  background: var(--bg-surface);
  border-left: 1px solid var(--border);
  display: flex;
  flex-direction: column;
}

.cart-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.5rem;
  border-bottom: 1px solid var(--border);
}

.cart-title {
  font-family: var(--font-serif);
  font-size: 1.3rem;
  font-weight: 700;
}

.cart-body {
  flex: 1;
  overflow-y: auto;
  padding: 1rem 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.cart-item {
  display: grid;
  grid-template-columns: 80px 1fr auto;
  gap: 1rem;
  align-items: start;
  padding: 1rem;
  background: var(--bg-elevated);
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
}

.cart-item-img {
  width: 80px;
  height: 80px;
  object-fit: cover;
  border-radius: var(--radius-sm);
  background: var(--bg-overlay);
}

.cart-item-name { font-weight: 600; font-size: .9rem; margin-bottom: .25rem; }
.cart-item-variant { font-size: .775rem; color: var(--text-muted); }
.cart-item-price { font-weight: 700; font-size: .95rem; }

.cart-qty {
  display: flex;
  align-items: center;
  gap: .5rem;
  margin-top: .5rem;
}
.cart-qty button {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: var(--bg-overlay);
  border: 1px solid var(--border);
  color: var(--text-primary);
  font-size: 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background var(--transition);
}
.cart-qty button:hover { background: var(--bg-surface); }
.cart-qty span { font-size: .875rem; min-width: 20px; text-align: center; }

.cart-footer {
  padding: 1.5rem;
  border-top: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.cart-subtotal {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
}
.cart-subtotal-label { font-size: .9rem; color: var(--text-secondary); }
.cart-subtotal-value { font-family: var(--font-serif); font-size: 1.4rem; font-weight: 700; }

.cart-checkout { width: 100%; padding: .9rem; font-size: 1rem; }

/* ============================================================
   Toast
   ============================================================ */
.toast-container {
  position: fixed;
  bottom: 1.5rem;
  right: 1.5rem;
  z-index: 500;
  display: flex;
  flex-direction: column;
  gap: .5rem;
  pointer-events: none;
}

.toast {
  padding: .8rem 1.2rem;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-left: 4px solid var(--success);
  border-radius: var(--radius-md);
  font-size: .875rem;
  font-weight: 500;
  box-shadow: var(--shadow-md);
  animation: slideInToast .25s ease forwards, fadeOutToast .3s ease 2.8s forwards;
  pointer-events: auto;
  max-width: 320px;
}

@keyframes slideInToast {
  from { opacity: 0; transform: translateX(20px); }
  to   { opacity: 1; transform: translateX(0); }
}
@keyframes fadeOutToast {
  to { opacity: 0; transform: translateX(20px); }
}

/* ============================================================
   Responsive
   ============================================================ */
@media (max-width: 1024px) {
