/* ============================================================
   LXRY — Ecommerce JS
   ============================================================ */
(function () {
  'use strict';

  /* ----------------------------------------------------------
     State
     ---------------------------------------------------------- */
  const cart = [];

  /* ----------------------------------------------------------
     Helpers
     ---------------------------------------------------------- */
  const $ = (sel, ctx = document) => ctx.querySelector(sel);
  const $$ = (sel, ctx = document) => Array.from(ctx.querySelectorAll(sel));

  function formatPrice(cents) {
    return '$' + (cents / 100).toFixed(2);
  }

  /* ----------------------------------------------------------
     Toast notifications
     ---------------------------------------------------------- */
  let toastContainer = null;

  function showToast(message) {
    if (!toastContainer) {
      toastContainer = document.createElement('div');
      toastContainer.className = 'toast-container';
      toastContainer.setAttribute('aria-live', 'polite');
      toastContainer.setAttribute('aria-atomic', 'false');
      document.body.appendChild(toastContainer);
    }

    const toast = document.createElement('div');
    toast.className = 'toast';
    toast.textContent = message;
    toastContainer.appendChild(toast);

    setTimeout(() => toast.remove(), 3200);
  }

  /* ----------------------------------------------------------
     Cart
     ---------------------------------------------------------- */
  const cartDrawer = $('#cart-drawer');
  const cartBackdrop = $('.cart-backdrop', cartDrawer);
  const cartCloseBtn = $('#cart-close');
  const cartBody = $('#cart-body');
  const cartSubtotalValue = $('#cart-subtotal-value');
  const cartCountEl = $('#cart-count');

  function openCart() {
    cartDrawer.classList.add('open');
    cartDrawer.setAttribute('aria-hidden', 'false');
    cartCloseBtn.focus();
    document.body.style.overflow = 'hidden';
  }

  function closeCart() {
    cartDrawer.classList.remove('open');
    cartDrawer.setAttribute('aria-hidden', 'true');
    document.body.style.overflow = '';
    // Return focus to the trigger
    const trigger = document.activeElement;
    if (cartDrawer.contains(trigger)) {
      $('#open-cart').focus();
    }
  }

  function addToCart(id, name, price, image, variant = '') {
    const existing = cart.find(i => i.id === id && i.variant === variant);
    if (existing) {
      existing.qty += 1;
    } else {
      cart.push({ id, name, price, image, variant, qty: 1 });
    }
    renderCart();
    openCart();
    showToast(`"${name}" added to your cart`);
  }

  function removeFromCart(id, variant) {
    const idx = cart.findIndex(i => i.id === id && i.variant === variant);
    if (idx > -1) cart.splice(idx, 1);
    renderCart();
  }

  function changeQty(id, variant, delta) {
    const item = cart.find(i => i.id === id && i.variant === variant);
    if (!item) return;
    item.qty = Math.max(0, item.qty + delta);
    if (item.qty === 0) removeFromCart(id, variant);
    else renderCart();
  }

  function renderCart() {
    const totalQty = cart.reduce((s, i) => s + i.qty, 0);
    cartCountEl.textContent = totalQty;
    cartCountEl.style.display = totalQty > 0 ? 'flex' : 'none';

    const totalCents = cart.reduce((s, i) => s + i.price * i.qty, 0);
    cartSubtotalValue.textContent = formatPrice(totalCents);

    cartBody.innerHTML = '';

    if (cart.length === 0) {
      const empty = document.createElement('p');
      empty.style.cssText = 'color:var(--text-muted);text-align:center;padding:2rem 0;font-size:.9rem;';
      empty.textContent = 'Your cart is empty.';
      cartBody.appendChild(empty);
      return;
    }

    cart.forEach(item => {
      const el = document.createElement('div');
      el.className = 'cart-item';
      el.innerHTML = `
        <img class="cart-item-img" src="${item.image}" alt="${item.name}" width="80" height="80">
        <div>
          <p class="cart-item-name">${item.name}</p>
          ${item.variant ? `<p class="cart-item-variant">${item.variant}</p>` : ''}
          <div class="cart-qty" role="group" aria-label="Quantity for ${item.name}">
            <button aria-label="Decrease quantity of ${item.name}"
              data-action="decrease" data-id="${item.id}" data-variant="${item.variant}">−</button>
            <span aria-live="polite">${item.qty}</span>
            <button aria-label="Increase quantity of ${item.name}"
              data-action="increase" data-id="${item.id}" data-variant="${item.variant}">+</button>
          </div>
        </div>
        <div style="text-align:right;display:flex;flex-direction:column;gap:.5rem;align-items:flex-end;">
          <p class="cart-item-price">${formatPrice(item.price * item.qty)}</p>
          <button class="btn-icon" style="width:28px;height:28px;font-size:.8rem;"
            aria-label="Remove ${item.name} from cart"
            data-action="remove" data-id="${item.id}" data-variant="${item.variant}">✕</button>
        </div>
      `;
      cartBody.appendChild(el);
    });
  }

