  cartBody.addEventListener('click', e => {
    const btn = e.target.closest('[data-action]');
    if (!btn) return;
    const { action, id, variant } = btn.dataset;
    if (action === 'increase') changeQty(id, variant, 1);
    if (action === 'decrease') changeQty(id, variant, -1);
    if (action === 'remove')   removeFromCart(id, variant);
  });

  $('#open-cart').addEventListener('click', openCart);
  cartCloseBtn.addEventListener('click', closeCart);
  cartBackdrop.addEventListener('click', closeCart);

  document.addEventListener('keydown', e => {
    if (e.key === 'Escape' && cartDrawer.classList.contains('open')) closeCart();
  });

  /* ----------------------------------------------------------
     Add-to-cart buttons (product grid)
     ---------------------------------------------------------- */
  document.addEventListener('click', e => {
    const btn = e.target.closest('[data-add-to-cart]');
    if (!btn) return;
    const { id, name, price, image, variant } = btn.dataset;
    addToCart(id, name, Number(price), image, variant);
  });

  /* ----------------------------------------------------------
     Wishlist toggle
     ---------------------------------------------------------- */
  document.addEventListener('click', e => {
    const btn = e.target.closest('[data-wishlist]');
    if (!btn) return;
    const pressed = btn.getAttribute('aria-pressed') === 'true';
    btn.setAttribute('aria-pressed', String(!pressed));
    btn.querySelector('svg').style.fill = pressed ? 'none' : 'currentColor';
    showToast(pressed ? 'Removed from wishlist' : 'Added to wishlist ♡');
  });

  /* ----------------------------------------------------------
     Category filter pills
     ---------------------------------------------------------- */
  $$('.category-pill').forEach(pill => {
    pill.addEventListener('click', () => {
      $$('.category-pill').forEach(p => p.setAttribute('aria-pressed', 'false'));
      pill.setAttribute('aria-pressed', 'true');
    });
  });

  /* ----------------------------------------------------------
     Countdown timers
     ---------------------------------------------------------- */
  function setCountdown(el, endTime) {
    function tick() {
      const diff = endTime - Date.now();
      if (diff <= 0) { el.textContent = 'Expired'; return; }

      const d = Math.floor(diff / 86400000);
      const h = Math.floor((diff % 86400000) / 3600000);
      const m = Math.floor((diff % 3600000) / 60000);
      const s = Math.floor((diff % 60000) / 1000);

      const pad = n => String(n).padStart(2, '0');

      el.innerHTML = `
        <div class="countdown-unit"><span class="countdown-value">${pad(h)}</span><span class="countdown-label">Hrs</span></div>
        <div class="countdown-unit"><span class="countdown-value">${pad(m)}</span><span class="countdown-label">Min</span></div>
        <div class="countdown-unit"><span class="countdown-value">${pad(s)}</span><span class="countdown-label">Sec</span></div>
      `;
    }
    tick();
    return setInterval(tick, 1000);
  }

  $$('[data-countdown]').forEach(el => {
    const hours = Number(el.dataset.countdown) || 24;
    const end = Date.now() + hours * 3600 * 1000;
    setCountdown(el, end);
  });

  /* ----------------------------------------------------------
     Mobile nav
     ---------------------------------------------------------- */
  const mobileNav = $('#mobile-nav');
  const menuToggle = $('#menu-toggle');
  const mobileClose = $('#mobile-nav-close');
  const mobileBackdrop = $('.mobile-nav-backdrop', mobileNav);

  function openMenu() {
    mobileNav.classList.add('open');
    mobileNav.setAttribute('aria-hidden', 'false');
    mobileClose.focus();
    document.body.style.overflow = 'hidden';
  }

  function closeMenu() {
    mobileNav.classList.remove('open');
    mobileNav.setAttribute('aria-hidden', 'true');
    document.body.style.overflow = '';
    menuToggle.focus();
  }

  menuToggle.addEventListener('click', openMenu);
  mobileClose.addEventListener('click', closeMenu);
  mobileBackdrop.addEventListener('click', closeMenu);

  document.addEventListener('keydown', e => {
    if (e.key === 'Escape' && mobileNav.classList.contains('open')) closeMenu();
  });

  // Close menu on nav link click
  $$('.mobile-nav-links a').forEach(a => a.addEventListener('click', closeMenu));

  /* ----------------------------------------------------------
     Intersection observer — fade-in on scroll
     ---------------------------------------------------------- */
  const fadeEls = $$('[data-fade]');
  if (fadeEls.length && 'IntersectionObserver' in window) {
    const io = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.style.opacity = '1';
          entry.target.style.transform = 'translateY(0)';
          io.unobserve(entry.target);
        }
      });
    }, { threshold: 0.08 });

    fadeEls.forEach((el, i) => {
      el.style.opacity = '0';
      el.style.transform = 'translateY(24px)';
      el.style.transition = `opacity .55s ease ${i * 0.05}s, transform .55s ease ${i * 0.05}s`;
      io.observe(el);
    });
  }

  /* ----------------------------------------------------------
     Newsletter form
     ---------------------------------------------------------- */
  const newsletterForm = $('#newsletter-form');
  if (newsletterForm) {
    newsletterForm.addEventListener('submit', e => {
      e.preventDefault();
      const emailInput = newsletterForm.querySelector('#newsletter-email');
      const success = $('#newsletter-success');

      if (!emailInput.value) {
        emailInput.setAttribute('aria-invalid', 'true');
        emailInput.focus();
        return;
      }

      newsletterForm.style.display = 'none';
      success.style.display = 'block';
      success.focus();
    });

    const emailInput = newsletterForm.querySelector('#newsletter-email');
    emailInput.addEventListener('input', () => {
      emailInput.removeAttribute('aria-invalid');
    });
  }

  /* ----------------------------------------------------------
     Hero CTA smooth scroll
     ---------------------------------------------------------- */
  $$('[data-scroll-to]').forEach(el => {
    el.addEventListener('click', e => {
      e.preventDefault();
      const target = document.getElementById(el.dataset.scrollTo);
      if (target) target.scrollIntoView({ behavior: 'smooth', block: 'start' });
    });
  });

  /* ----------------------------------------------------------
     Initial render
     ---------------------------------------------------------- */
  renderCart();

})();

